const search=document.getElementById('search');
if(document.body.classList.contains('map-page')){
 const ns='http://www.w3.org/2000/svg';
 const svg=(name,attrs)=>{const el=document.createElementNS(ns,name);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el};
 const root=document.querySelector('.map-root'),canvas=document.querySelector('.map-scroll');
 const orbit=svg('svg',{viewBox:'0 0 160 160',class:'orbit','aria-hidden':'true'});orbit.append(svg('circle',{cx:80,cy:80,r:72}),svg('circle',{cx:80,cy:80,r:77}));root.prepend(orbit);
 const icons=['M5 25V17M13 25V9M21 25V3M2 28h26','M8 8h16v16H8zM12 12h8v8h-8zM12 3v5M20 3v5M12 24v5M20 24v5M3 12h5M3 20h5M24 12h5M24 20h5','M4 5h24v7H4zM8 15h16v5H8zM12 23h8v4h-8z','M7 9a11 11 0 1 1-2 14M3 4v8h8M12 16h8M16 12v8','M5 8h8v8H5zM19 16h8v8h-8zM13 12h10v4M9 16v8h10','M13 3h7v7h-7zM3 23h7v7H3zM23 23h7v7h-7zM16 10v7M6 23v-6h20v6'];
 document.querySelectorAll('.section-head').forEach((head,i)=>{const icon=svg('svg',{viewBox:'0 0 32 32',class:'branch-icon','aria-hidden':'true'});icon.append(svg('path',{d:icons[i],'stroke-linecap':'round','stroke-linejoin':'round'}));head.insertBefore(icon,head.querySelector('div'))});
 const wires=svg('svg',{class:'map-wires','aria-hidden':'true'});canvas.prepend(wires);
 function draw(){wires.replaceChildren();const base=canvas.getBoundingClientRect(),r=root.querySelector('span').getBoundingClientRect(),x=r.x+r.width/2-base.x,y=r.bottom-base.y;wires.setAttribute('viewBox',`0 0 ${base.width} ${base.height}`);document.querySelectorAll('.atlas .group').forEach((g,i)=>{const b=g.getBoundingClientRect(),tx=b.x+b.width/2-base.x,ty=b.top-base.y;const bend=y+Math.min(26,(ty-y)/2);const d=`M${x} ${y} V${bend} H${tx} V${ty}`;wires.append(svg('path',{d,class:'map-wire'}));if(ty-y<100){const pulse=svg('path',{d,class:'map-pulse'});pulse.style.animationDelay=`-${i*1.2}s`;wires.append(pulse)}})}
 new ResizeObserver(draw).observe(canvas);draw();
 const button=document.createElement('button');button.className='motion';button.textContent='暂停光效';button.setAttribute('aria-pressed','false');document.querySelector('.toolbar').append(button);button.addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');button.textContent=paused?'开启光效':'暂停光效';button.setAttribute('aria-pressed',String(paused))});
}
if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();let count=0;document.querySelectorAll('.group').forEach(g=>{let found=0;g.querySelectorAll('.card').forEach(c=>{const hit=(c.textContent+' '+g.querySelector('h2').textContent).toLowerCase().includes(q);c.classList.toggle('search-muted',!!q&&!hit);c.classList.toggle('search-match',!!q&&hit);if(hit)found++});g.classList.toggle('search-muted',!!q&&!found);count+=found});document.getElementById('empty').hidden=count>0});
if(document.querySelector('.group')){const observer=new IntersectionObserver(entries=>{const v=entries.filter(e=>e.isIntersecting);if(v.length){document.querySelectorAll('aside a').forEach(a=>a.classList.toggle('active',a.hash==='#'+v[0].target.id))}},{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('.group').forEach(g=>observer.observe(g))}
